-- Guest Hub H9 fix 2 (16 Nov 2026, Ahmed — DECISIONS.md 2026-11-16 «Guest Hub: standby mode»). Generated by
-- scripts/hub-standby-migration.mjs from scripts/hub-standby-migration.src.sql and the latest definitions of the functions it
-- edits — never edited once applied (CLAUDE.md §12: a fix is a new migration).
--   «وضع الاستعداد» per branch («الفريق والتقارير» → «فريق الاستقبال»: the switch, OFF by default, and «مدة الانتظار
--   (دقائق)» 1–30): the first guest message of an episode, or a guest message after a staff reply, waits that many minutes
--   for a staff reply — only while a staff slot of the branch is on shift; once the assistant replied in the exchange the
--   follow-ups are answered at once; a tap on our own button is never delayed (opt-out words, the «إلغاء» flow and staff
--   numbers never queue a turn). The wait is the turn's due time: no reply, no typing call (so the message stays unread), no
--   staff alert. A staff reply inside it → the turn only tags (the assistant stood down); its end → one reply to every
--   pending message. pg_cron hub-standby (every 10 seconds) asks hub-agent for the due ones. «التقارير» counts both ends.
-- No unit mode, licence or switch changes (the new switch ships OFF). No phone number in this file.


-- ───────────────────────────────────────────── 1. the settings ─────────────────────────────────────────────
alter table public.hub_team_branches
  add column standby_on boolean not null default false,
  add column standby_minutes integer not null default 5 check (standby_minutes between 1 and 30);
comment on column public.hub_team_branches.standby_on is '«وضع الاستعداد: انتظر رد الفريق قبل رد المساعد» (Ahmed, 16 Nov 2026) — OFF by default; hub_team_standby_save only.';
comment on column public.hub_team_branches.standby_minutes is '«مدة الانتظار (دقائق)» of «وضع الاستعداد», 1–30.';
drop trigger hub_team_branches_audit on public.hub_team_branches;
create trigger hub_team_branches_audit after insert or update or delete on public.hub_team_branches
  for each row execute function internal.audit('branch_slug', 'resume_minutes', 'escalate_minutes', 'standby_on', 'standby_minutes');

-- ───────────────────────────────────────────── 2. the turn's wait ─────────────────────────────────────────────
alter table public.hub_turns
  add column standby_until timestamptz,
  add column standby_outcome text check (standby_outcome is null or standby_outcome in ('staff', 'assistant')),
  add column standby_posted_at timestamptz;
comment on column public.hub_turns.standby_until is '«وضع الاستعداد»: the end of the wait for a staff reply (the turn is due then); NULL = no wait.';
comment on column public.hub_turns.standby_outcome is '«وضع الاستعداد»: staff = a staff reply inside the wait (the assistant stood down) · assistant = no staff reply, the assistant answered after it.';
create index hub_turns_standby on public.hub_turns (due_at) where status = 'pending' and standby_until is not null;

-- the last staff message of an episode (a reply from the inbox or the branch phone; never the note «ضغطة زر من الجوال», never
-- a saved automatic text of the phone)
create function internal.hub_last_staff_at(p_conversation uuid) returns timestamptz
language sql stable security definer set search_path = '' as $$
  select max(m.created_at) from public.hub_messages m
   where m.conversation_id = p_conversation and m.direction = 'out' and m.author in ('staff', 'phone') and m.kind <> 'note'
$$;

-- the assistant already replied in this exchange: a reply turn ran since the last staff message
create function internal.hub_assistant_engaged(p_conversation uuid) returns boolean
language sql stable security definer set search_path = '' as $$
  select exists (select 1 from public.hub_turns x where x.conversation_id = p_conversation and x.kind = 'reply' and x.status in ('running', 'done')
                    and x.claimed_at > coalesce(internal.hub_last_staff_at(p_conversation), '-infinity'::timestamptz))
$$;

-- the twin of _shared/hub/standby.ts → standbyMinutes: the minutes to wait for this guest message, or NULL (no wait)
create function internal.hub_standby_minutes(p_conversation uuid, p_message uuid, p_kind text, p_at timestamptz default now()) returns integer
language sql stable security definer set search_path = '' as $$
  select case
    when p_kind <> 'reply' then null
    -- a tap on one of our own buttons is never delayed
    when exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id')) then null
    when internal.hub_assistant_engaged(p_conversation) then null
    when not exists (select 1 from public.hub_staff_slots s where s.branch_slug = u.branch_slug and s.active and internal.hub_slot_covers(s, p_at)) then null
    else t.standby_minutes end
    from public.hub_conversations c join public.hub_units u on u.id = c.unit_id join public.hub_team_branches t on t.branch_slug = u.branch_slug
   where c.id = p_conversation and t.standby_on and t.standby_minutes between 1 and 30
$$;

-- the countdown of «المحادثات»: the end of a wait still running
create function internal.hub_standby_until(p_conversation uuid) returns timestamptz
language sql stable security definer set search_path = '' as $$
  select max(t.standby_until) from public.hub_turns t
   where t.conversation_id = p_conversation and t.status = 'pending' and t.standby_outcome is null and t.standby_until > now()
$$;

-- a staff reply inside the wait: the assistant stands down — the turn only tags (the conversation is «مع موظف»; the branch's
-- «عودة المساعد» minutes apply from here as for any staff reply)
create function internal.hub_standby_staff() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  update public.hub_turns set standby_outcome = 'staff', kind = 'tag', due_at = now()
   where conversation_id = new.conversation_id and status = 'pending' and standby_until is not null and standby_outcome is null;
  return null;
end;
$$;
create trigger hub_messages_standby_staff after insert on public.hub_messages
  for each row when (new.direction = 'out' and new.author in ('staff', 'phone') and new.kind <> 'note')
  execute function internal.hub_standby_staff();

-- the wait's end, to the second (pg_cron every 10 seconds): a due standby turn asks hub-agent for a sweep — once per 30 s
create function public.hub_standby_kick() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_n integer;
  v_req bigint;
begin
  update public.hub_turns set standby_posted_at = now()
   where status = 'pending' and standby_until is not null and due_at <= now()
     and (standby_posted_at is null or standby_posted_at < now() - interval '30 seconds');
  get diagnostics v_n = row_count;
  if v_n > 0 then v_req := internal.hub_agent_post('sweep'); end if;
  return jsonb_build_object('ok', true, 'due', v_n, 'request', v_req);
end;
$$;

-- ───────────────────────────────────────────── 3. «الفريق والتقارير» → «فريق الاستقبال» ─────────────────────────────────────────────
create function public.hub_team_standby_save(p_branch text, p_on boolean, p_minutes integer) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  o public.hub_team_branches;
  v_batch uuid;
begin
  if not internal.can('hub_team', 'edit') or not internal.can_branch(p_branch) then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into o from public.hub_team_branches where branch_slug = p_branch for update;
  if o.branch_slug is null then raise exception 'not_found' using errcode = '22023'; end if;
  if p_on is null then raise exception 'hub_team_standby' using errcode = '22023'; end if;
  if p_minutes is null or p_minutes not between 1 and 30 then raise exception 'hub_team_standby_minutes' using errcode = '22023'; end if;
  v_batch := internal.begin_batch();
  update public.hub_team_branches set standby_on = p_on, standby_minutes = p_minutes, updated_at = now(), updated_by = auth.uid() where branch_slug = p_branch;
  return jsonb_build_object('ok', true, 'batch_id', v_batch, 'previous', jsonb_build_object('standby_on', o.standby_on, 'standby_minutes', o.standby_minutes));
end;
$$;

-- «المحاكي»: the unit's branch standby and whether anyone is on shift now (assistant: view)
create function public.hub_standby_status(p_unit text) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  u public.hub_units;
  t public.hub_team_branches;
begin
  if not internal.can('assistant', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  select * into u from public.hub_units where key = p_unit;
  if u.id is null then raise exception 'not_found' using errcode = '22023'; end if;
  select * into t from public.hub_team_branches where branch_slug = u.branch_slug;
  return jsonb_build_object('on', coalesce(t.standby_on, false), 'minutes', coalesce(t.standby_minutes, 5),
    'on_shift', exists (select 1 from public.hub_staff_slots s where s.branch_slug = u.branch_slug and s.active and internal.hub_slot_covers(s, now())));
end;
$$;

revoke execute on function internal.hub_last_staff_at(uuid), internal.hub_assistant_engaged(uuid), internal.hub_standby_minutes(uuid, uuid, text, timestamptz),
  internal.hub_standby_until(uuid), internal.hub_standby_staff() from public, anon, authenticated;
revoke execute on function public.hub_standby_kick() from public, anon, authenticated;
grant execute on function public.hub_standby_kick() to service_role;
revoke execute on function public.hub_team_standby_save(text, boolean, integer), public.hub_standby_status(text) from public, anon;
grant execute on function public.hub_team_standby_save(text, boolean, integer), public.hub_standby_status(text) to authenticated;

select cron.schedule('hub-standby', '10 seconds', 'select public.hub_standby_kick()');


-- ───────────────────────────────────────────── 4. the functions it edits ─────────────────────────────────────────────

create or replace function public.hub_turn_queue(p_conversation uuid, p_message uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  u public.hub_units;
  g public.guest_profiles;
  st jsonb;
  v_turn uuid;
  v_due timestamptz;
  v_kind text;
  -- at most 3 seconds (Ahmed, 15 Nov 2026 — the wait was the largest part of a reply's time)
  v_burst integer := least(greatest(internal.hub_setting_int('hub_burst_ms', 2000), 0), 3000);
  v_test_mode boolean;
  -- «وضع الاستعداد» (16 Nov 2026)
  v_wait integer;
  v_tap boolean;
  v_until timestamptz;
  v_woke boolean;
begin
  select * into c from public.hub_conversations where id = p_conversation for update;
  if c.id is null or c.state = 'closed' then return jsonb_build_object('queued', false, 'reason', 'closed'); end if;
  if not exists (select 1 from public.hub_messages m where m.id = p_message and m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest') then
    return jsonb_build_object('queued', false, 'reason', 'not_guest');
  end if;
  select * into u from public.hub_units where id = c.unit_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  if g.hub_blocked_at is not null then return jsonb_build_object('queued', false, 'reason', 'blocked'); end if;
  st := internal.hub_assistant_state(u);
  if not (st ->> 'active')::boolean then
    perform internal.hub_to_team(c, case when st ->> 'reason' = 'unit_off' then 'assistant_off' else st ->> 'reason' end);
    return jsonb_build_object('queued', false, 'reason', st ->> 'reason');
  end if;
  v_test_mode := st ->> 'mode' = 'test';
  -- the try while the API credit is exhausted (at most every 30 minutes): reserved here
  if (st ->> 'credit_try')::boolean then
    update public.hub_alerts set payload = payload || jsonb_build_object('last_try_at', now()) where kind = 'api_credit' and acknowledged_at is null and not is_test;
  end if;
  if v_test_mode then
    -- a conversation that existed before «تجربة»: its run starts now
    if c.test_state is null then
      update public.hub_conversations set test_state = 'new' where id = c.id;
      c.test_state := 'new';
    end if;
    -- H6c: «بانتظار موظف» (a hand-off with no staff reply yet) is answered by the assistant in a test run as well
    v_kind := case when c.test_state = 'closed' then 'tag' else 'reply' end;
  else
    -- H6c: «بانتظار موظف» → the assistant keeps answering what it can; «مع موظف» → silent (tagging) until the branch's
    -- «عودة المساعد» minutes of staff silence, then the guest's message resumes it
    v_kind := case when c.state = 'human' and internal.hub_human_phase(c, u) is null then 'tag' else 'reply' end;
  end if;
  v_tap := exists (select 1 from public.hub_messages m where m.id = p_message and (m.kind in ('interactive', 'button_reply') or m.payload ? 'button_id'));
  v_woke := v_tap and exists (select 1 from public.hub_turns x where x.conversation_id = c.id and x.status = 'pending' and x.standby_until > now() and x.standby_outcome is null);
  -- a pending turn of this conversation takes the message (the burst; a wait of «وضع الاستعداد» takes every message until it
  -- ends — one reply to all of them); a tap on our own button ends the wait at once
  update public.hub_turns set inbound_message_ids = case when p_message = any (inbound_message_ids) then inbound_message_ids else inbound_message_ids || p_message end,
         due_at = case when v_tap and standby_until > now() and standby_outcome is null then least(due_at, now() + make_interval(secs => v_burst / 1000.0)) else due_at end,
         standby_until = case when v_tap and standby_until > now() and standby_outcome is null then now() else standby_until end
   where conversation_id = c.id and status = 'pending'
  returning id, due_at, standby_until into v_turn, v_due, v_until;
  if v_turn is not null then
    return jsonb_build_object('queued', true, 'joined', true, 'turn_id', v_turn, 'due_at', v_due, 'standby_until', case when v_until > now() then v_until end, 'woke', v_woke);
  end if;
  -- «وضع الاستعداد»: the minutes to wait for a staff reply first (NULL = none — today's burst)
  v_wait := internal.hub_standby_minutes(c.id, p_message, v_kind);
  insert into public.hub_turns (conversation_id, unit_id, inbound_message_ids, first_inbound_id, kind, due_at, is_test, standby_until)
  values (c.id, c.unit_id, array[p_message], p_message, v_kind,
          case when v_wait is not null then now() + make_interval(mins => v_wait) else now() + make_interval(secs => v_burst / 1000.0) end, c.is_test,
          case when v_wait is not null then now() + make_interval(mins => v_wait) end)
  on conflict do nothing
  returning id, due_at into v_turn, v_due;
  if v_turn is null then
    select t.id, t.due_at into v_turn, v_due from public.hub_turns t where t.first_inbound_id = p_message;
    return jsonb_build_object('queued', false, 'reason', 'duplicate', 'turn_id', v_turn);
  end if;
  return jsonb_build_object('queued', true, 'turn_id', v_turn, 'due_at', v_due, 'kind', v_kind, 'standby_until', case when v_wait is not null then v_due end);
end;
$$;

create or replace function public.hub_turn_claim(p_turn uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  t public.hub_turns;
  c public.hub_conversations;
  u public.hub_units;
  ch public.hub_channels;
  g public.guest_profiles;
  st jsonb;
  v_mode text;
  v_state text;
  v_draft jsonb;
  v_first boolean;
  v_rate jsonb;
  v_text text;
  v_phase text;
begin
  select * into t from public.hub_turns where id = p_turn for update skip locked;
  if t.id is null then return jsonb_build_object('claimed', false, 'reason', 'taken'); end if;
  if t.status <> 'pending' then return jsonb_build_object('claimed', false, 'reason', t.status); end if;
  if t.due_at > now() then return jsonb_build_object('claimed', false, 'reason', 'not_due', 'due_at', t.due_at); end if;
  if exists (select 1 from public.hub_turns x where x.conversation_id = t.conversation_id and x.status = 'running') then
    return jsonb_build_object('claimed', false, 'reason', 'busy');
  end if;
  select * into c from public.hub_conversations where id = t.conversation_id for update;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  st := internal.hub_assistant_state(u);
  if c.state = 'closed' or not (st ->> 'active')::boolean or g.hub_blocked_at is not null then
    update public.hub_turns set status = 'skipped', finished_at = now(), error = coalesce(case when c.state = 'closed' then 'closed' when g.hub_blocked_at is not null then 'blocked' end, st ->> 'reason') where id = t.id;
    perform internal.hub_to_team(c, coalesce(st ->> 'reason', 'assistant_off'));
    return jsonb_build_object('claimed', false, 'reason', coalesce(st ->> 'reason', 'closed'));
  end if;
  v_mode := case st ->> 'mode' when 'test' then 'test' when 'shadow' then 'shadow' else 'live' end;
  v_state := case when v_mode = 'test' then coalesce(c.test_state, 'new') else c.state end;
  -- H6c: waiting (handed, no staff reply) / resume (staff silent for the branch's minutes) / null (silent)
  v_phase := case when v_mode = 'test' then case when v_state = 'human' then 'waiting' end when c.state = 'human' then internal.hub_human_phase(c, u) end;
  update public.hub_turns set status = 'running', claimed_at = now(), started_at = coalesce(started_at, now()), attempts = attempts + 1, mode = v_mode,
                              kind = case when v_state = 'closed' or (v_state = 'human' and v_phase is null) then 'tag' else kind end,
                              -- «وضع الاستعداد»: no staff reply in the wait — the assistant answers after it
                              standby_outcome = case when standby_until is not null and standby_outcome is null and kind = 'reply'
                                                       and not (v_state = 'closed' or (v_state = 'human' and v_phase is null)) then 'assistant' else standby_outcome end
   where id = t.id returning * into t;
  select to_jsonb(d) - 'is_test' into v_draft from public.hub_drafts d where d.conversation_id = c.id and d.status = 'open' and d.sim = (v_mode = 'test');
  v_first := not exists (select 1 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'out' and m.kind <> 'note'
                          and m.status not in ('rejected', 'superseded', 'failed') and (v_mode = 'test' or m.status <> 'test'));
  select string_agg(m.body, ' ' order by m.sent_at) into v_text from public.hub_messages m where m.id = any (t.inbound_message_ids);
  -- the rate limits of spec §7.4: guest messages processed per phone per hour, assistant replies per conversation per
  -- hour, the same text three times in ten minutes
  v_rate := jsonb_build_object(
    'phone_hour', (select coalesce(sum(cardinality(x.inbound_message_ids)), 0) from public.hub_turns x join public.hub_conversations y on y.id = x.conversation_id
                    where y.guest_profile_id = g.id and x.id <> t.id and x.status in ('done', 'running') and x.kind = 'reply' and x.created_at > now() - interval '1 hour'),
    'replies_hour', (select count(*) from public.hub_messages m where m.conversation_id = c.id and m.author = 'assistant' and m.direction = 'out'
                      and m.created_at > now() - interval '1 hour' and not coalesce((m.payload ->> 'notice')::boolean, false)),
    'repeated', (select count(*) >= 2 from public.hub_messages m where m.conversation_id = c.id and m.direction = 'in' and m.author = 'guest'
                  and not (m.id = any (t.inbound_message_ids)) and m.created_at > now() - interval '10 minutes'
                  and btrim(lower(coalesce(m.body, ''))) = btrim(lower(coalesce(v_text, ''))) and coalesce(v_text, '') <> '')
                  -- Ahmed, 14 Nov 2026 (H6 pass 4): a repeat is suppressed ONLY when the assistant already answered that same text in
                  -- this episode, and answered its LATEST earlier copy (that copy's reply turn sent the guest a message) — so a copy
                  -- whose earlier copies got no reply from the assistant (the team owned the conversation, the model failed …) is
                  -- answered; 21:51 of 14 Nov: the 21:48 copies came while the phone owned it, so the third is answered
                  and coalesce((select exists (select 1 from public.hub_turns z join public.hub_messages o on o.turn_id = z.id
                                                where z.conversation_id = c.id and m2.id = any (z.inbound_message_ids) and z.kind = 'reply' and z.status = 'done'
                                                  and o.direction = 'out' and o.author = 'assistant' and o.status not in ('test', 'rejected', 'superseded', 'failed'))
                                  from public.hub_messages m2
                                 where m2.conversation_id = c.id and m2.direction = 'in' and m2.author = 'guest' and not (m2.id = any (t.inbound_message_ids))
                                   and btrim(lower(coalesce(m2.body, ''))) = btrim(lower(coalesce(v_text, '')))
                                 order by m2.created_at desc, m2.sent_at desc, m2.id desc limit 1), false),
    'phone_max', internal.hub_setting_int('hub_rate_phone_hour', 30), 'replies_max', internal.hub_setting_int('hub_rate_replies_hour', 20));
  return jsonb_build_object(
    'claimed', true,
    'turn', jsonb_build_object('id', t.id, 'kind', t.kind, 'mode', v_mode, 'attempts', t.attempts, 'is_test', t.is_test),
    'conversation', jsonb_build_object('id', c.id, 'state', v_state, 'real_state', c.state, 'state_before_human', c.state_before_human, 'human_phase', v_phase,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'failed_understandings', c.failed_understandings,
      'priority', c.priority, 'topics', to_jsonb(c.topics), 'tags', to_jsonb(c.tags), 'out_of_scope', c.out_of_scope, 'first_reply', v_first,
      'created_at', c.created_at, 'is_test', c.is_test),
    'unit', jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'branch', u.branch_slug, 'name_ar', u.name_ar, 'name_en', u.name_en,
      'mode', u.assistant_mode, 'skills', to_jsonb(u.skills), 'persona', u.persona_live,
      -- H7: «الفويس» and «الصور»
      'media', jsonb_build_object('voice', u.voice_on, 'images', u.images_on),
      'venue', (select jsonb_build_object('name_ar', v.name_ar, 'name_en', v.name_en, 'menu', v.menu) from public.dining_venues v where v.id = u.dining_venue_id)),
    'channel', jsonb_build_object('address', ch.address, 'sending_enabled', ch.sending_enabled),
    'guest', jsonb_build_object(
      -- a name from a past booking only (spec §2.9) — never the WhatsApp profile name
      'first_name', case when exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and not r.is_test)
                         then nullif(split_part(btrim(coalesce(g.name, '')), ' ', 1), '') end,
      'returning', exists (select 1 from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= internal.riyadh_today() and not r.is_test),
      'language', g.language,
      -- H8: a returning guest's previous room (a confirmed past stay on the same phone) — its card comes first
      'last_room', (select jsonb_build_object('branch', r.branch, 'room', rt.slug) from public.reservations r join public.room_types rt on rt.id = r.room_type_id
                     where r.phone = g.phone and r.status = 'confirmed' and not r.is_test and r.check_out <= internal.riyadh_today() order by r.check_out desc limit 1),
      -- H8: the «إياب» members' prices only for a member with recorded consent (applied by code, never inferred)
      'member', g.club_joined_at is not null and g.consent = 'granted',
      -- H8: «يُعامَل كضيف للتجربة» — a test reservation that never takes a room
      'test_guest', internal.hub_test_guest(g.phone)),
    -- H8: the live «إياب» members' codes of this branch, for a member only
    'member_codes', case when g.club_joined_at is not null and g.consent = 'granted' then
      (select coalesce(jsonb_agg(distinct o.promo_code), '[]'::jsonb) from public.offers o
        where o.audience = 'members' and o.category = 'individuals' and o.live is not null and o.archived_at is null and not o.is_test and o.promo_code is not null
          and (o.valid_to is null or o.valid_to >= internal.riyadh_today()) and (o.branches is null or cardinality(o.branches) = 0 or u.branch_slug = any (o.branches)))
      else '[]'::jsonb end,
    'messages', (select coalesce(jsonb_agg(jsonb_build_object('id', m.id, 'kind', m.kind, 'body', m.body, 'payload', m.payload, 'sent_at', m.sent_at,
                                                              'provider_message_id', m.provider_message_id,
                                                              -- H7: the stored file and a transcript already made (a retried turn)
                                                              'media_path', m.media_path, 'media_mime', m.media_mime, 'transcript', m.transcript) order by m.sent_at, m.created_at), '[]')
                   from public.hub_messages m where m.id = any (t.inbound_message_ids)),
    'history', (select coalesce(jsonb_agg(jsonb_build_object('author', case when h.direction = 'in' then 'guest' when h.author in ('staff', 'phone') then 'staff' else 'us' end, 'body', coalesce(h.body, h.transcript)) order by h.sent_at), '[]')
                  from (select m.* from public.hub_messages m
                         where m.conversation_id = c.id and not (m.id = any (t.inbound_message_ids)) and m.kind <> 'note' and coalesce(m.body, m.transcript) is not null
                           and m.status not in ('rejected', 'superseded', 'failed', 'pending_approval') and (v_mode = 'test' or m.status <> 'test')
                         order by m.sent_at desc limit 12) h),
    'draft', v_draft,
    -- H9: a departure check sent today and not answered yet — a typed answer («بمدد يومين», «طالع الساعة 11») is understood
    -- as «سأغادر في موعدي» / «أرغب في التمديد»; a late check-out question stays an ordinary question
    'departure', (select jsonb_build_object('id', d.id, 'ref', d.nazeel_ref) from public.hub_departures d
                   where d.phone = g.phone and d.branch_slug = u.branch_slug and d.answer is null and d.is_test = c.is_test
                     and d.check_state in ('accepted', 'sent', 'delivered', 'read', 'test') and d.departure_date = internal.riyadh_today()
                   order by d.check_at desc limit 1),
    -- H7: the unit's transcribed seconds today and the cap
    'voice', internal.hub_voice_state(u.id),
    -- the guest's own bookings (same phone) for a booking-status answer: ref, status, branch, dates only
    'bookings', (select coalesce(jsonb_agg(jsonb_build_object('ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out)
                                           order by r.check_in desc), '[]')
                   from (select * from public.reservations r where r.phone = g.phone and (r.is_test = c.is_test or (r.is_test and internal.hub_test_guest(g.phone)))
                          order by r.created_at desc limit 5) r),
    'licences', (select coalesce(jsonb_object_agg(l.topic_key, l.mode), '{}') from public.hub_licences l where l.unit_id = u.id),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', x.key, 'label_en', x.label_en, 'label_ar', x.label_ar, 'parent_key', x.parent_key, 'always_handoff', x.always_handoff) order by x.sort, x.key), '[]')
                 from public.hub_topics x where x.status = 'active' and not x.is_test),
    'settings', jsonb_build_object(
      'confidence_floor', coalesce((select (s.value #>> '{}')::numeric from public.settings s where s.key = 'hub_confidence_floor'), 0.7),
      'cards_per_turn', internal.hub_setting_int('hub_cards_per_turn', 5), 'reply_max_chars', internal.hub_setting_int('hub_reply_max_chars', 600),
      'failed_max', internal.hub_setting_int('hub_failed_understanding_max', 2), 'resume_minutes', internal.hub_resume_minutes(u.branch_slug), 'group_min_rooms', internal.hub_setting_int('hub_group_min_rooms', 5),
      'models', (select s.value from public.settings s where s.key = 'hub_models'), 'prices', (select s.value from public.settings s where s.key = 'hub_model_prices'),
      -- the site's own switch: prices only while the branch shows them (spec §2.5 rule 11)
      'show_prices', coalesce((select (s.value ->> u.branch_slug)::boolean from public.settings s where s.key = 'show_prices'), false),
      -- H8: the branch's «الحجز الفوري» (off keeps the booking link as the fallback) and the instant limits (the reason texts)
      'instant_booking', coalesce((select (s.value ->> u.branch_slug)::boolean from public.settings s where s.key = 'instant_booking'), false),
      'limits', coalesce(internal.setting('instant_limits'), '{"same_day_cutoff": "20:00", "max_nights": 30}'::jsonb)),
    -- the shared forbidden list the guard reads (internal.hub_forbidden_terms — never copied)
    'forbidden', to_jsonb(internal.hub_forbidden_terms()),
    'rate', v_rate,
    'budget', internal.hub_budget_state(),
    'today', internal.riyadh_today());
end;
$$;

create or replace function public.hub_agent_kick() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  v_due integer;
  v_lab integer;
  v_jobs integer;
  v_alerts integer;
  v_req bigint;
begin
  select count(*) into v_due from public.hub_turns t
   where (t.status = 'pending' and (t.due_at <= now() - interval '20 seconds' or (t.standby_until is not null and t.due_at <= now()))) or (t.status = 'running' and t.claimed_at < now() - interval '3 minutes');
  select count(*) into v_lab from public.hub_eval_results r join public.hub_eval_runs u on u.id = r.run_id
   where u.status in ('queued', 'running') and (r.status = 'pending' or (r.status = 'running' and r.claimed_at < now() - interval '4 minutes'));
  select count(*) into v_jobs from public.hub_card_jobs j where j.status = 'pending' or (j.status = 'running' and j.claimed_at < now() - interval '4 minutes');
  -- H7b: a «تعلّم:» the router's call missed
  v_jobs := v_jobs + (select count(*) from public.hub_teach_jobs t where t.status = 'pending' or (t.status = 'running' and t.claimed_at < now() - interval '4 minutes'));
  select count(*) into v_alerts from public.hub_alerts a where a.kind in ('flagged_wrong', 'spike') and a.sent_at is null and a.acknowledged_at is null and not a.is_test;
  if v_due + v_lab + v_jobs + v_alerts > 0 then v_req := internal.hub_agent_post('sweep'); end if;
  return jsonb_build_object('ok', true, 'due', v_due, 'lab', v_lab, 'jobs', v_jobs, 'alerts', v_alerts, 'request', v_req);
end;
$$;

create or replace function public.hub_thread(p_conversation uuid) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  c public.hub_conversations;
  g public.guest_profiles;
  u public.hub_units;
  ch public.hub_channels;
  st jsonb;
begin
  select * into c from public.hub_conversations where id = p_conversation;
  if c.id is null or not internal.can_unit(c.unit_id, 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  select * into g from public.guest_profiles where id = c.guest_profile_id;
  select * into u from public.hub_units where id = c.unit_id;
  select * into ch from public.hub_channels where id = c.channel_id;
  st := internal.hub_assistant_state(u);
  return jsonb_build_object(
    'conversation', jsonb_build_object(
      'id', c.id, 'unit_id', u.id, 'unit_key', u.key, 'unit_kind', u.kind, 'branch', u.branch_slug,
      'unit_name', coalesce((select v.name_ar from public.dining_venues v where v.id = u.dining_venue_id), u.name_ar),
      'channel_kind', ch.kind, 'channel_address', ch.address, 'sending_enabled', ch.sending_enabled,
      'state', c.state, 'state_before_human', c.state_before_human, 'test_state', c.test_state, 'owner_kind', c.owner_kind, 'owner_staff_id', c.owner_staff_id,
      'owner_name', internal.staff_name(c.owner_staff_id), 'human_reason', c.human_reason, 'priority', c.priority,
      'language', coalesce(c.language, g.language), 'window_expires_at', c.window_expires_at, 'waiting_since', c.waiting_since,
      'last_guest_at', c.last_guest_at, 'last_staff_at', c.last_staff_at, 'tags', to_jsonb(c.tags), 'topics', to_jsonb(c.topics),
      'referral', c.referral, 'created_at', c.created_at, 'closed_at', c.closed_at, 'is_test', c.is_test,
      'can_edit', internal.can_unit(c.unit_id, 'edit'),
      'unit_mode', u.assistant_mode,
      'assistant', jsonb_build_object('active', (st ->> 'active')::boolean, 'mode', st ->> 'mode', 'reason', st ->> 'reason'),
      'can_release', internal.can_unit(c.unit_id, 'edit') and c.state = 'human' and (st ->> 'active')::boolean and st ->> 'mode' in ('shadow', 'licensed'),
      'can_pause', internal.can_unit(c.unit_id, 'edit') and u.assistant_mode <> 'off',
      -- «وضع الاستعداد»: the countdown «المساعد يرد بعد m:ss»
      'standby_until', internal.hub_standby_until(c.id),
      'templates_approved', (select coalesce(jsonb_agg(t.language order by t.language), '[]') from public.hub_templates t
                              where t.channel_id = c.channel_id and t.name = 'hub_reply_ready' and t.status = 'APPROVED')),
    'guest', jsonb_build_object(
      'id', g.id, 'name', g.name, 'wa_name', g.wa_profile_name, 'label', internal.hub_guest_label(g), 'phone', g.phone, 'language', g.language,
      'member', g.club_joined_at is not null, 'consent', g.consent, 'opted_out', g.wa_opt_out_at is not null, 'blocked', g.hub_blocked_at is not null,
      'marketing_hold', g.marketing_hold_at is not null, 'tags', to_jsonb(g.tags), 'notes', g.notes,
      'stays', (select count(*) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'last_stay', (select max(r.check_out) from public.reservations r where r.profile_id = g.id and r.status = 'confirmed' and r.check_out <= (now() at time zone 'Asia/Riyadh')::date and not r.is_test),
      'bookings', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'ref', r.ref, 'status', r.status, 'branch', r.branch, 'check_in', r.check_in, 'check_out', r.check_out)
                                             order by r.check_in desc), '[]')
                     from (select * from public.reservations r where r.profile_id = g.id and internal.can_branch(r.branch) order by r.check_in desc limit 10) r)),
    'messages', (select coalesce(jsonb_agg(jsonb_build_object(
                   'id', m.id, 'direction', m.direction, 'author', m.author, 'staff_id', m.staff_id, 'staff_name', internal.staff_name(m.staff_id),
                   'kind', m.kind, 'body', m.body, 'payload', m.payload, 'language', m.language, 'media_path', m.media_path, 'media_mime', m.media_mime,
                   -- H7: «تفريغ صوتي» and the image's category
                   'transcript', m.transcript, 'transcript_seconds', m.transcript_seconds, 'media_category', m.media_category, 'media_status', m.media_status,
                   'media_purged', m.media_purged_at is not null or m.media_pending_delete, 'status', m.status, 'error_code', m.error_code,
                   'sent_at', m.sent_at, 'purged', m.purged_at is not null, 'unanswered', exists (select 1 from public.hub_unanswered q where q.message_id = m.id),
                   'translation', m.translation_ar, 'approved_by_name', internal.staff_name(m.approved_by), 'approved_at', m.approved_at,
                   'edited_before_send', m.edited_before_send, 'turn_id', m.turn_id,
                   'sources', (select coalesce(jsonb_agg(jsonb_build_object('id', k.id, 'key', k.key, 'title', coalesce(k.live ->> 'title_ar', k.title_ar)) order by k.key), '[]')
                                 from public.hub_knowledge_cards k where k.id = any (m.source_card_ids)))
                   order by m.sent_at, m.created_at), '[]') from public.hub_messages m where m.conversation_id = c.id),
    'templates', (select coalesce(jsonb_agg(t order by t ->> 'at'), '[]') from (
                    select jsonb_build_object('source', 'booking', 'template', w.template, 'meta_template', w.meta_template, 'status', w.status, 'ref', w.ref,
                                              'branch', w.branch, 'language', w.language, 'at', w.created_at) t
                      from public.whatsapp_messages w join public.reservations r on r.id = w.reservation_id
                     where r.profile_id = g.id and internal.can_branch(r.branch) and w.status not in ('skipped')
                    union all
                    select jsonb_build_object('source', 'eyab', 'template', e.template, 'status', e.status, 'branch', e.branch, 'language', e.language, 'at', e.created_at)
                      from public.eyab_messages e where e.profile_id = g.id and e.status not in ('skipped') and internal.can_branch(e.branch)) s),
    'events', (select coalesce(jsonb_agg(jsonb_build_object('kind', e.kind, 'from', e.from_value, 'to', e.to_value, 'reason', e.reason, 'at', e.at,
                                                           'actor', internal.staff_name(e.actor_staff_id)) order by e.at, e.id), '[]')
                 from public.hub_conversation_events e where e.conversation_id = c.id),
    'episodes', (select coalesce(jsonb_agg(jsonb_build_object('id', x.id, 'unit_name', xu.name_ar, 'state', x.state, 'created_at', x.created_at, 'closed_at', x.closed_at)
                                           order by x.created_at desc), '[]')
                   from public.hub_conversations x join public.hub_units xu on xu.id = x.unit_id
                  where x.guest_profile_id = g.id and x.id <> c.id and internal.can_unit(x.unit_id, 'view')),
    'transfer_units', (select coalesce(jsonb_agg(jsonb_build_object('id', t.id, 'name', coalesce(v.name_ar, t.name_ar)) order by t.sort), '[]')
                         from public.hub_units t left join public.dining_venues v on v.id = t.dining_venue_id where t.status = 'active' and t.id <> u.id),
    'team', (select coalesce(jsonb_agg(jsonb_build_object('staff_id', s.user_id, 'full_name', s.full_name) order by s.full_name), '[]')
               from public.hub_unit_members m join public.staff s on s.user_id = m.staff_id
               join public.staff_permissions sp on sp.user_id = s.user_id and sp.section = 'inbox' and sp.level >= 'edit'
              where m.unit_id = u.id and s.active),
    'timers', internal.hub_timers());
end;
$$;

create or replace function public.hub_inbox_list(p jsonb default '{}'::jsonb) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_tab text := coalesce(nullif(p ->> 'tab', ''), 'waiting');
  v_q text := btrim(coalesce(p ->> 'q', ''));
  v_digits text := regexp_replace(coalesce(p ->> 'q', ''), '[^0-9]', '', 'g');
  v_limit integer := least(greatest(coalesce((p ->> 'limit')::integer, 50), 1), 200);
  v_before timestamptz := nullif(p ->> 'before', '')::timestamptz;
  v_blocked boolean := coalesce((p ->> 'blocked')::boolean, false);
  v_rows jsonb;
  v_counts jsonb;
  v_units jsonb;
begin
  if not internal.can('inbox', 'view') then raise exception 'not allowed' using errcode = '42501'; end if;
  if v_tab not in ('waiting', 'assistant', 'drafts', 'all', 'closed') then raise exception 'hub_tab' using errcode = '22023'; end if;
  with base as (
    select c.*, u.key as unit_key, coalesce(v.name_ar, u.name_ar) as unit_name, ch.kind as channel_kind, g as gp,
           c.state = 'human' and c.waiting_since is not null as t_waiting,
           c.state not in ('human', 'closed') as t_assistant,
           exists (select 1 from public.hub_messages d where d.conversation_id = c.id and d.status = 'pending_approval') as t_drafts,
           c.state = 'closed' as t_closed,
           greatest(coalesce(c.last_guest_at, c.created_at), coalesce(c.last_staff_at, c.created_at), coalesce(c.last_assistant_at, c.created_at), c.created_at) as last_at
      from public.hub_conversations c
      join public.hub_units u on u.id = c.unit_id
      left join public.dining_venues v on v.id = u.dining_venue_id
      join public.hub_channels ch on ch.id = c.channel_id
      join public.guest_profiles g on g.id = c.guest_profile_id
     where internal.can_unit(c.unit_id, 'view')
       and (g.hub_blocked_at is not null) = v_blocked
       and (nullif(p ->> 'unit', '') is null or u.id::text = p ->> 'unit' or u.key = p ->> 'unit')
       and (nullif(p ->> 'state', '') is null or c.state = p ->> 'state')
       and (nullif(p ->> 'channel', '') is null or ch.kind = p ->> 'channel')
       and (nullif(p ->> 'language', '') is null or coalesce(c.language, g.language) = p ->> 'language')
       and (nullif(p ->> 'topic', '') is null or (p ->> 'topic') = any (c.topics))
       and (nullif(p ->> 'tag', '') is null or (p ->> 'tag') = any (c.tags))
       and (nullif(p ->> 'owner', '') is null
            or (p ->> 'owner' = 'me' and c.owner_kind = 'staff' and c.owner_staff_id = auth.uid())
            or (p ->> 'owner' = 'none' and c.owner_kind is null)
            or (p ->> 'owner' in ('phone', 'assistant') and c.owner_kind = p ->> 'owner')
            or (c.owner_staff_id::text = p ->> 'owner'))
       and (v_q = ''
            or (v_q ~* '^AR-' and exists (select 1 from public.reservations r where r.profile_id = g.id and r.ref ilike v_q || '%'))
            or (v_q !~* '^AR-' and (coalesce(g.name, '') ilike '%' || v_q || '%' or coalesce(g.wa_profile_name, '') ilike '%' || v_q || '%'
                                    or (char_length(v_digits) >= 3 and coalesce(g.phone, '') like '%' || v_digits || '%'))))
  ),
  counts as (
    select jsonb_build_object('waiting', count(*) filter (where t_waiting), 'assistant', count(*) filter (where t_assistant),
                              'drafts', count(*) filter (where t_drafts), 'all', count(*) filter (where not t_closed), 'closed', count(*) filter (where t_closed)) as j
      from base
  ),
  page as (
    select * from base b
     where ((v_tab = 'waiting' and b.t_waiting) or (v_tab = 'assistant' and b.t_assistant) or (v_tab = 'drafts' and b.t_drafts)
            or (v_tab = 'all' and not b.t_closed) or (v_tab = 'closed' and b.t_closed))
       and (v_before is null or b.last_at < v_before)
     order by b.last_at desc, b.id desc
     limit v_limit + 1
  )
  select (select j from counts),
         coalesce((select jsonb_agg(jsonb_build_object(
           'id', x.id, 'unit_id', x.unit_id, 'unit_key', x.unit_key, 'unit_name', x.unit_name, 'channel_kind', x.channel_kind,
           'state', x.state, 'owner_kind', x.owner_kind, 'owner_staff_id', x.owner_staff_id, 'owner_name', internal.staff_name(x.owner_staff_id),
           'tags', to_jsonb(x.tags), 'topics', to_jsonb(x.topics), 'priority', x.priority, 'language', coalesce(x.language, (x.gp).language),
           'waiting_since', x.waiting_since, 'window_expires_at', x.window_expires_at, 'standby_until', internal.hub_standby_until(x.id), 'is_test', x.is_test, 'blocked', (x.gp).hub_blocked_at is not null,
           'name', internal.hub_guest_label(x.gp), 'phone_last4', right(coalesce((x.gp).phone, ''), 4), 'last_at', x.last_at,
           'unread', (select count(*) from public.hub_messages i where i.conversation_id = x.id and i.direction = 'in'
                        and i.sent_at > coalesce(greatest(x.last_staff_at, x.last_assistant_at), '-infinity'::timestamptz)),
           'last', (select jsonb_build_object('author', l.author, 'kind', l.kind, 'line', left(split_part(coalesce(l.body, ''), chr(10), 1), 120), 'at', l.sent_at)
                      from public.hub_messages l where l.conversation_id = x.id and l.kind <> 'note' order by l.sent_at desc, l.created_at desc limit 1))
           order by x.last_at desc, x.id desc) from page x), '[]'::jsonb)
    into v_counts, v_rows;
  select coalesce(jsonb_agg(jsonb_build_object('id', u.id, 'key', u.key, 'kind', u.kind, 'name', coalesce(v.name_ar, u.name_ar), 'status', u.status) order by u.sort), '[]') into v_units
    from public.hub_units u left join public.dining_venues v on v.id = u.dining_venue_id where internal.can_unit(u.id, 'view');
  return jsonb_build_object('rows', case when jsonb_array_length(v_rows) > v_limit then v_rows - v_limit else v_rows end,
                            'more', jsonb_array_length(v_rows) > v_limit, 'counts', v_counts, 'units', v_units, 'timers', internal.hub_timers(),
                            'inbox_on', internal.hub_setting_bool('hub_inbox_on'), 'can_edit', internal.can('inbox', 'edit'));
end;
$$;

create or replace function public.hub_team_get() returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_edit boolean := internal.can('hub_team', 'edit');
  v_admin boolean := internal.is_system_admin();
begin
  if not internal.can('hub_team', 'view') then raise exception 'forbidden' using errcode = '42501'; end if;
  return jsonb_build_object(
    'now', now(), 'can_edit', v_edit, 'is_system_admin', v_admin,
    'branches', (select coalesce(jsonb_agg(jsonb_build_object(
        'slug', b.slug, 'name', b.name_ar, 'can_edit', v_edit and internal.can_branch(b.slug),
        'resume_minutes', t.resume_minutes, 'escalate_minutes', t.escalate_minutes, 'standby_on', t.standby_on, 'standby_minutes', t.standby_minutes,
        'channel', (select ch.sending_enabled from public.hub_channels ch where ch.id = internal.hub_branch_channel(b.slug)),
        'slots', (select coalesce(jsonb_agg(jsonb_build_object('id', s.id, 'position', s.position, 'name', s.name,
                    'phone', case when v_edit and internal.can_branch(b.slug) then s.phone else internal.hub_mask_phone(s.phone) end,
                    'role', s.role, 'days', to_jsonb(s.days), 'start_time', to_char(s.start_time, 'HH24:MI'), 'end_time', to_char(s.end_time, 'HH24:MI'),
                    'active', s.active, 'test_as_guest', s.test_as_guest, 'consent_at', s.consent_at,
                    'on_shift', s.active and internal.hub_slot_covers(s, now())) order by s.position), '[]'::jsonb)
                    from public.hub_staff_slots s where s.branch_slug = b.slug)
      ) order by b.sort, b.slug), '[]'::jsonb)
      from public.branches b join public.hub_team_branches t on t.branch_slug = b.slug where internal.can_branch(b.slug)),
    'report', jsonb_build_object(
      'send_time', (select to_char(c.send_time, 'HH24:MI') from public.hub_report_config c where c.id),
      'recipients', (select coalesce(jsonb_agg(jsonb_build_object('id', r.id, 'position', r.position, 'name', r.name,
                       'phone', case when v_admin then r.phone else internal.hub_mask_phone(r.phone) end, 'staff_user_id', r.staff_user_id,
                       'staff_name', internal.staff_name(r.staff_user_id), 'active', r.active, 'test_as_guest', r.test_as_guest, 'consent_at', r.consent_at,
                       'mine', r.staff_user_id = auth.uid()) order by r.position), '[]'::jsonb) from public.hub_report_recipients r),
      'email_recipients', (select count(*) from public.booking_notification_recipients r where r.scope = 'hub_summary' and r.active and r.filter_confirmed_at is not null),
      'last', (select jsonb_build_object('day', d.day, 'built_at', d.built_at) from public.hub_daily_reports d order by d.day desc limit 1),
      'staff_users', case when v_admin then (select coalesce(jsonb_agg(jsonb_build_object('id', s.user_id, 'name', s.full_name) order by s.full_name), '[]'::jsonb)
                                               from public.staff s where s.active) end));
end;
$$;

create or replace function public.report_hub(p_branch text, p_from date, p_to date) returns jsonb
language plpgsql stable security definer set search_path = '' as $$
declare
  v_br text[] := internal.metrics_branches('reports', p_branch);
  v_a timestamptz;
  v_b timestamptz;
  v_rate numeric := coalesce((internal.setting('wa_message_cost') ->> 'utility')::numeric, 0);
  v_out jsonb;
begin
  perform internal.metrics_period(p_from, p_to);
  v_a := p_from::timestamp at time zone 'Asia/Riyadh';
  v_b := (p_to + 1)::timestamp at time zone 'Asia/Riyadh';
  with units as (
    select u.id, u.key, u.name_ar, u.branch_slug, u.sort from public.hub_units u where u.branch_slug = any (v_br) and not u.is_test),
  conv as (
    select c.* from public.hub_conversations c where not c.is_test and c.created_at >= v_a and c.created_at < v_b and c.unit_id in (select id from units)),
  -- the assistant's first reply: the episode's first live reply turn that answered (from the episode's first guest message —
  -- the conversation's start); the turns, never the message table (no text is read by a report)
  first_ai as (
    select t.conversation_id, min(t.finished_at) as at from public.hub_turns t join conv c on c.id = t.conversation_id
     where t.kind = 'reply' and t.status = 'done' and t.mode = 'live' and not t.is_test
       and exists (select 1 from jsonb_array_elements_text(coalesce(t.decision -> 'actions', '[]'::jsonb)) a where a not in ('noop', 'tag', 'handoff')) group by 1),
  ai_rt as (
    select c.unit_id, extract(epoch from a.at - c.created_at) / 60.0 as min from conv c join first_ai a on a.conversation_id = c.id where a.at >= c.created_at),
  ho as (
    select h.* from public.hub_handoffs h where not h.is_test and h.created_at >= v_a and h.created_at < v_b and h.unit_id in (select id from units)),
  staff_rt as (select h.unit_id, extract(epoch from h.first_reply_at - h.created_at) / 60.0 as min from ho h where h.first_reply_at is not null),
  drafts as (
    select d.*, c.unit_id from public.hub_drafts d join conv c on c.id = d.conversation_id where d.kind = 'stay' and not d.sim and not d.is_test),
  bk as (
    select r.* from public.reservations r where not r.is_test and r.booking_source = 'assistant_whatsapp' and r.created_at >= v_a and r.created_at < v_b and r.branch = any (v_br)),
  topics as (
    select k, count(*) as n from public.hub_turns t cross join lateral unnest(t.topics) k
     where not t.is_test and t.kind = 'reply' and t.created_at >= v_a and t.created_at < v_b and t.unit_id in (select id from units)
       and k not in ('greeting', 'thanks_closing') group by k order by n desc, k limit 10)
  select jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'units', (select coalesce(jsonb_agg(jsonb_build_object(
        'key', un.key, 'name_ar', un.name_ar, 'branch', un.branch_slug,
        'conversations', (select count(*) from conv c where c.unit_id = un.id),
        'handed_off', (select count(distinct h.conversation_id) from ho h where h.unit_id = un.id),
        'assistant_only', (select count(*) from conv c where c.unit_id = un.id and exists (select 1 from first_ai a where a.conversation_id = c.id)
                            and not exists (select 1 from ho h where h.conversation_id = c.id)),
        'ai_median_min', (select round(percentile_cont(0.5) within group (order by x.min)::numeric, 1) from ai_rt x where x.unit_id = un.id),
        'ai_p90_min', (select round(percentile_cont(0.9) within group (order by x.min)::numeric, 1) from ai_rt x where x.unit_id = un.id),
        'staff_median_min', (select round(percentile_cont(0.5) within group (order by x.min)::numeric, 1) from staff_rt x where x.unit_id = un.id),
        'staff_p90_min', (select round(percentile_cont(0.9) within group (order by x.min)::numeric, 1) from staff_rt x where x.unit_id = un.id),
        'quoted', (select count(*) from drafts d where d.unit_id = un.id and d.quote is not null),
        'booked', (select count(*) from drafts d where d.unit_id = un.id and d.reservation_id is not null),
        -- «وضع الاستعداد»: the waits answered by staff inside them / by the assistant after them
        'standby_staff', (select count(*) from public.hub_turns t where t.unit_id = un.id and not t.is_test and t.standby_outcome = 'staff'
                           and t.created_at >= v_a and t.created_at < v_b),
        'standby_assistant', (select count(*) from public.hub_turns t where t.unit_id = un.id and not t.is_test and t.standby_outcome = 'assistant'
                               and t.created_at >= v_a and t.created_at < v_b),
        'model_cost_usd', (select round(coalesce(sum(x.cost_usd), 0), 4) from public.hub_usage_daily x
                            where x.unit_id = un.id and not x.is_test and x.source in ('turn', 'staff') and x.day between p_from and p_to))
        order by un.sort, un.key), '[]'::jsonb) from units un),
    'bookings', (select jsonb_build_object('instant', count(*) filter (where b.confirmation = 'instant'), 'request', count(*) filter (where b.confirmation is distinct from 'instant'),
                                           'confirmed', count(*) filter (where b.status = 'confirmed'),
                                           'revenue', coalesce(sum(internal.res_revenue(b.id)) filter (where b.status = 'confirmed'), 0)) from bk b),
    'sales_requests', (select jsonb_build_object('hall', count(*) filter (where e.request_type = 'event'), 'group', count(*) filter (where e.request_type <> 'event'))
                         from public.partner_enquiries e where not e.is_test and e.page_url = 'whatsapp' and e.created_at >= v_a and e.created_at < v_b
                           and (e.branch = any (v_br) or e.branch = 'both')),
    'topics', (select coalesce(jsonb_agg(jsonb_build_object('key', t.k, 'label_ar', coalesce(x.label_ar, t.k), 'count', t.n) order by t.n desc, t.k), '[]'::jsonb)
                 from topics t left join public.hub_topics x on x.key = t.k),
    'whatsapp', (select jsonb_build_object('templates', n, 'estimate_usd', round(n * v_rate, 4)) from (
        select (select count(*) from public.hub_staff_sends s where not s.is_test and s.status in ('accepted', 'sent', 'delivered', 'read') and s.created_at >= v_a and s.created_at < v_b)
             + (select count(*) from public.whatsapp_messages w join bk b on b.ref = w.ref where w.status in ('accepted', 'sent', 'delivered', 'read')) as n) z))
  into v_out;
  return internal.money(v_out);
end;
$$;


-- ───────────────────────────────────────────── 5. the test lab: the standby conversations ─────────────────────────────────────────────
do $$
declare v_sort integer := coalesce((select max(sort) + 1 from public.hub_test_items), 0);
begin
  insert into public.hub_test_items (key, unit_key, language, messages, context, expect, note, tags, added_from, sort)
  select e ->> 'key', e ->> 'unit', e ->> 'language', e -> 'messages', coalesce(e -> 'context', '{}'::jsonb), e -> 'expect', e ->> 'note',
         array(select jsonb_array_elements_text(e -> 'tags')), 'seed', v_sort + (o - 1)::integer
    from jsonb_array_elements($standby_bank$[{"key":"c138","unit":"airport-road","language":"ar","messages":["[burst] السلام عليكم ‖ عندكم مواقف سيارات؟ ‖ وكم سعر الإفطار؟"],"expect":{"action":"conversation","steps":[{"outcome":"answer"}]},"note":"no staff reply in the wait: the three messages answered in one reply at its end (parking and the breakfast price, both sourced)","tags":["conversation","standby"],"context":{}},{"key":"c139","unit":"shafa-road","language":"en","messages":["[burst] Hello ‖ Is parking free at the hotel?"],"expect":{"action":"conversation","steps":[{"outcome":"answer"}]},"note":"English: the wait ended with no staff reply — one reply to both messages","tags":["conversation","standby"],"context":{}},{"key":"c140","unit":"airport-road","language":"ar","messages":["[held] عندكم مواقف؟","[staff] نعم، المواقف مجانية لنزلائنا.","طيب وكم سعر الإفطار؟"],"expect":{"action":"conversation","steps":[{"outcome":"none"},{"outcome":"none"}]},"note":"a staff reply inside the wait: the assistant stood down; the guest's next message within «عودة المساعد» stays with staff","tags":["conversation","standby"],"context":{}},{"key":"c141","unit":"airport-road","language":"ar","messages":["[held] كم سعر الإفطار؟","[staff] أهلًا بك، الإفطار متاح يوميًا.","[wait:16]","[burst] شكرًا ‖ وعندكم مواقف سيارات؟"],"expect":{"action":"conversation","steps":[{"outcome":"none"},{"outcome":["answer","reply"]}]},"note":"after a staff reply and 16 minutes of staff silence the guest's message waits again; no staff reply → the assistant answers both","tags":["conversation","standby"],"context":{}},{"key":"c142","unit":"shafa-road","language":"ar","messages":["[burst] السلام عليكم ‖ أبغى أحجز غرفة لشخصين","من 20 ديسمبر إلى 22 ديسمبر"],"expect":{"action":"conversation","steps":[{"outcome":["ask","reply"]},{"outcome":["ask","quote"]}]},"note":"the first exchange waited; the dates after the assistant's question are a follow-up — answered at once (no second wait)","tags":["conversation","standby"],"context":{}}]$standby_bank$::jsonb) with ordinality as x(e, o)
  on conflict (key) do nothing;
end $$;
